window.__ModuleLoader__.load({
  id: 'dsh-locale-fr',
  factory(require) {
    return {
      inject: ['locale'],
      apply(ctx) {
        const disposers = [];
        disposers.push(ctx.locale.addLanguage({ id: 'fr', label: 'Français', fallback: 'en' }));
        for (const [ns, dict] of Object.entries(DICTS)) {
          try {
            disposers.push(ctx.locale.register(ns, 'fr', dict));
          } catch (error) {
            console.warn('[locale-fr] enregistrement impossible pour', ns, error);
          }
        }
        return () => {
          for (const dispose of disposers) dispose();
        };
      },
    };
  },
});
